package dev.agenttrust.core;
import java.util.UUID;
import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockHttpSession;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.web.server.ResponseStatusException;
import static org.junit.jupiter.api.Assertions.*;
class WorkspaceSessionsTest {
 DemoUser user(String role){return new DemoUser("test","unused",UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),role);}
 MockHttpSession session(DemoUser user){var s=new MockHttpSession();var context=SecurityContextHolder.createEmptyContext();context.setAuthentication(UsernamePasswordAuthenticationToken.authenticated(user,null,user.getAuthorities()));s.setAttribute("SPRING_SECURITY_CONTEXT",context);return s;}
 @Test void onlyOwnSessionsVisibleAndOpaqueHandlesAreNotCredentials(){var registry=new WorkspaceSessions();var owner=user("viewer");var foreign=user("admin");var one=session(owner);var two=session(owner);registry.observe(owner,one);registry.observe(owner,two);registry.observe(foreign,session(foreign));var page=registry.list(owner,one);assertEquals(2,page.entries().size());assertEquals(1,page.entries().stream().filter(WorkspaceSessions.Entry::current).count());assertFalse(page.deploymentAuthority());assertEquals("current-core-instance-observed-app-sessions",page.coverage());assertTrue(page.entries().stream().noneMatch(r->r.handle().toString().equals(one.getId())));}
 @Test void anotherOwnAppSessionCanEndButNotCurrentOrForeign(){var registry=new WorkspaceSessions();var owner=user("editor");var foreign=user("admin");var one=session(owner);var two=session(owner);registry.observe(owner,one);registry.observe(owner,two);var rows=registry.list(owner,one).entries();var other=rows.stream().filter(v->!v.current()).findFirst().orElseThrow();var current=rows.stream().filter(WorkspaceSessions.Entry::current).findFirst().orElseThrow();assertThrows(ResponseStatusException.class,()->registry.revoke(foreign,session(foreign),other.handle()));assertThrows(ResponseStatusException.class,()->registry.revoke(owner,one,current.handle()));assertFalse(two.isInvalid());assertEquals(1,registry.revoke(owner,one,other.handle()).entries().size());assertTrue(two.isInvalid());assertFalse(one.isInvalid());}
 @Test void expiredOrReassignedSecurityContextCannotBeRevokedByOldOwner(){var registry=new WorkspaceSessions();var owner=user("admin");var one=session(owner);var two=session(owner);registry.observe(owner,one);registry.observe(owner,two);var handle=registry.list(owner,one).entries().stream().filter(v->!v.current()).findFirst().orElseThrow().handle();var foreign=user("viewer");var context=SecurityContextHolder.createEmptyContext();context.setAuthentication(UsernamePasswordAuthenticationToken.authenticated(foreign,null,foreign.getAuthorities()));two.setAttribute("SPRING_SECURITY_CONTEXT",context);assertThrows(ResponseStatusException.class,()->registry.revoke(owner,one,handle));assertFalse(two.isInvalid());one.invalidate();assertEquals(0,registry.list(owner,null).entries().size());}
 @Test void inventoryIsBoundedAndReportsPartialCoverage(){var registry=new WorkspaceSessions();var owner=user("viewer");MockHttpSession current=null;for(int i=0;i<27;i++){current=session(owner);registry.observe(owner,current);}var page=registry.list(owner,current);assertEquals(25,page.entries().size());assertTrue(page.truncated());}
}
